import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.7','Zugbeeinflussung, Ziff.')
F1="Diese Vorschriften gelten für alle Eisenbahnen, die mit einem Zugbeeinflussungssystem ausgerüstet sind. Standardisierte Systeme sind in den Anlagen zu diesem Reglement beschrieben. Dies gilt auch für Signalisierungssysteme mit integrierten Zugbeeinflussungsfunktionen. Für Systeme, die in den Anlagen dieses Reglements nicht beschrieben sind, regeln die ISB in ihren Betriebsvorschriften die Funktionen des Systems und deren Wirkung auf die EVU sowie die allfälligen betrieblichen Einschränkungen im Störungsfall."
add("1","Geltungsbereich","Für welche Eisenbahnen gelten die Vorschriften § ?","Für alle Eisenbahnen, die mit einem Zugbeeinflussungssystem ausgerüstet sind.",["Für alle Eisenbahnen ohne Ausnahme.","Nur für Eisenbahnen mit Normalspur.","Nur für Eisenbahnen mit Zahnradstrecken."],F1)
add("1","Beschreibung standardisierter Systeme","Wo sind standardisierte Zugbeeinflussungssysteme § beschrieben?","In den Anlagen zu diesem Reglement.",["In der Fahrordnung.","In der Streckentabelle.","In den Betriebsvorschriften der EVU."],F1)
add("1","Signalisierungssysteme integriert","Was gilt § für Signalisierungssysteme mit integrierten Zugbeeinflussungsfunktionen?","Die Vorschriften gelten auch für sie.",["Die Vorschriften gelten für sie nicht.","Sie gelten nur auf Strecken mit Signalsystem N.","Sie gelten nur bei Störungen."],F1)
addm("1","Regelung nicht beschriebener Systeme","Was regeln die ISB § in ihren Betriebsvorschriften für Systeme, die in den Anlagen nicht beschrieben sind (Mehrfachauswahl).",["Die Funktionen des Systems","Die Wirkung auf die EVU","Die allfälligen betrieblichen Einschränkungen im Störungsfall"],["Die Ausbildung der LF","Die Kosten der Ausrüstung","Die Zulassung der Fahrzeuge"],F1)
F2="Die Zugbeeinflussung funktioniert hauptsächlich im Hintergrund und unterstützt den LF mit dem Ziel, den Endpunkt der Zustimmung zur Fahrt nicht zu überfahren und die zulässigen Höchstgeschwindigkeiten nicht zu überschreiten. Die Zugbeeinflussung gewährleistet überdies, dass der LF die sicherheitsrelevanten Informationen von Signalen berücksichtigt."
addm("2.1","Ziele der Zugbeeinflussung","Welche Ziele verfolgt die Zugbeeinflussung §? (Mehrfachauswahl).",["Den Endpunkt der Zustimmung zur Fahrt nicht zu überfahren","Die zulässigen Höchstgeschwindigkeiten nicht zu überschreiten","Zu gewährleisten, dass der LF die sicherheitsrelevanten Informationen von Signalen berücksichtigt"],["Den Fahrplan einzuhalten","Den Energieverbrauch zu senken","Den LF vollständig zu ersetzen"],F2)
add("2.1","Wirkungsweise Hintergrund","Wie funktioniert die Zugbeeinflussung § hauptsächlich?","Im Hintergrund, sie unterstützt den LF.",["Sie ersetzt den LF.","Sie wird nur bei Störungen aktiviert.","Sie wird nur auf Verlangen des FDL aktiviert."],F2)
F3="Die Zugbeeinflussung gewährleistet die punktuelle oder kontinuierliche Überwachung in Abhängigkeit des eingesetzten Systems, abgestimmt auf die Infrastruktur sowie Dichte und Art des Verkehrs."
addm("2.2","Arten der Überwachung","Welche Arten der Überwachung gewährleistet die Zugbeeinflussung §? (Mehrfachauswahl).",["Die punktuelle Überwachung","Die kontinuierliche Überwachung"],["Die stichprobenartige Überwachung durch den FDL","Die zeitgesteuerte Überwachung","Die manuelle Überwachung durch den ZVB"],F3)
addm("2.2","Abhängigkeit der Überwachung","Wovon hängt die Art der Überwachung § ab (Mehrfachauswahl).",["Vom eingesetzten System","Von der Infrastruktur","Von der Dichte und Art des Verkehrs"],["Vom Wetter","Vom Alter des LF","Von der Zugnummer"],F3)
F4="Die Funktionstüchtigkeit der Ausrüstung auf den Triebfahrzeugen und Steuerwagen ist mindestens einmal pro Tag nach den Vorgaben der EVU zu prüfen. Das Ergebnis ist zu protokollieren."
add("2.3","Häufigkeit Funktionskontrolle","Wie oft ist die Funktionstüchtigkeit der Zugbeeinflussung auf den Triebfahrzeugen und Steuerwagen § mindestens zu prüfen?","Mindestens einmal pro Tag.",["Mindestens einmal pro Woche.","Vor jeder einzelnen Fahrt.","Mindestens einmal pro Monat."],F4)
add("2.3","Vorgaben Funktionskontrolle","Nach wessen Vorgaben ist die Funktionstüchtigkeit der Zugbeeinflussung § zu prüfen?","Nach den Vorgaben der EVU.",["Nach den Vorgaben der ISB.","Nach den Vorgaben des BAV.","Nach den Vorgaben des FDL."],F4)
add("2.3","Ergebnis Funktionskontrolle","Was ist mit dem Ergebnis der Funktionskontrolle der Zugbeeinflussung § zu tun?","Es ist zu protokollieren.",["Es ist nur bei Störungen festzuhalten.","Es ist dem FDL mündlich zu melden.","Es ist nur bei einem negativen Ergebnis zu melden."],F4)
F5="Die Zugbeeinflussung wirkt auf das Bremssystem und das Fahrzeugleitgerät der betroffenen Fahrzeuge. Die Informationen der Infrastruktur werden über Streckengeräte (Balisen, Gleismagnete, strahlendes Kabel) übertragen. Auf dem Fahrzeug wird die Information über einen Empfänger entgegengenommen."
addm("2.4","Wirkung auf Fahrzeuge","Auf welche Einrichtungen der betroffenen Fahrzeuge wirkt die Zugbeeinflussung §? (Mehrfachauswahl).",["Auf das Bremssystem","Auf das Fahrzeugleitgerät"],["Auf die Fahrleitung","Auf die Weichenantriebe","Auf die Zugsammelschiene"],F5)
addm("2.4","Streckengeräte","Über welche Streckengeräte werden die Informationen der Infrastruktur § übertragen (Mehrfachauswahl).",["Balisen","Gleismagnete","Strahlendes Kabel"],["Lichtsignale","Achszähler","Isolierstösse"],F5)
add("2.4","Empfänger auf dem Fahrzeug","Wie wird die Information der Infrastruktur auf dem Fahrzeug § entgegengenommen?","Über einen Empfänger.",["Über die Fahrleitung.","Über eine Funkdurchsage des FDL.","Durch Ablesen durch den LF."],F5)
add("3.1","Wirkung auf geführtes Fahrzeug","Auf welches Fahrzeug wirkt die Zugbeeinflussung § mit genormten Funktionen?","Auf das Fahrzeug, das den Zug direkt oder indirekt führt.",["Auf alle Fahrzeuge des Zuges.","Nur auf Wagen.","Nur auf das Fahrzeug am Zugschluss."],"Die Zugbeeinflussung wirkt mit genormten Funktionen auf das Fahrzeug, das den Zug direkt oder indirekt führt.")
F6="Gewisse Funktionen setzen Bremskurven ein. Diese werden aufgrund der Streckendaten (Funktion aktiv, Distanz, Zielgeschwindigkeit, Neigung usw.) und der Fahrzeugdaten ermittelt (Zuggattung, Bremsverhältnis, Zuglänge usw.). Die Streckendaten werden nach gewünschter Funktion programmiert. Sie können fest oder variabel (nach Signalbegriff, Stellung der Schutzelemente usw.) sein. Der LF erfasst die Fahrzeugdaten über eine Bedienoberfläche."
addm("3.2","Streckendaten","Welche Angaben gehören § zu den Streckendaten (Mehrfachauswahl).",["Funktion aktiv","Distanz","Zielgeschwindigkeit","Neigung"],["Zuggattung","Bremsverhältnis","Zuglänge"],F6)
addm("3.2","Fahrzeugdaten","Welche Angaben gehören § zu den Fahrzeugdaten (Mehrfachauswahl).",["Zuggattung","Bremsverhältnis","Zuglänge"],["Distanz","Zielgeschwindigkeit","Neigung"],F6)
addm("3.2","variable Streckendaten","Wonach können variable Streckendaten § richten (Mehrfachauswahl).",["Nach dem Signalbegriff","Nach der Stellung der Schutzelemente"],["Nach dem Wetter","Nach der Tageszeit","Nach der Zugnummer"],F6)
add("3.2","Erfassung Fahrzeugdaten","Wie erfasst der LF die Fahrzeugdaten §?","Über eine Bedienoberfläche.",["Über Balisen.","Über den FDL.","Über das strahlende Kabel."],F6)
F7="Grundsätzlich werden folgende Funktionen unterschieden: Halt; Rangierhalt; Warnung; Überwachung (der Höchstgeschwindigkeit, des Zugs, der Betriebsart, der Strecke, der Rangierbewegung, der Bremskurve, der Zielgeschwindigkeit); Abfahrverhinderung; Überwachung bei Umschaltung Adhäsions-/Zahnradbetrieb."
addm("3.3","Funktionen","Welche Funktionen der Zugbeeinflussung werden § unterschieden (Mehrfachauswahl).",["Halt","Rangierhalt","Warnung","Überwachung","Abfahrverhinderung","Überwachung bei Umschaltung Adhäsions-/Zahnradbetrieb"],["Abfahrerlaubnis","Fahrstrassenprüfung"],F7)
F8="Die Funktion «Halt» löst bei Erhalt des entsprechenden Telegramms eine Zwangsbremsung aus. Diese Funktion kommt bei den Hauptsignalen und zum Schutz von Bahnübergangsanlagen zum Einsatz. Dabei handelt es sich um eine punktuelle Überwachung. Die Funktion «Rangierhalt» stellt eine Variante der Funktion «Halt» dar. Sie löst bei Erhalt des entsprechenden Telegramms eine Zwangsbremsung aus, sofern sich das Fahrzeug im Rangiermodus befindet."
add("3.3.1","Halt Auslösung","Was löst die Funktion «Halt» § bei Erhalt des entsprechenden Telegramms aus?","Eine Zwangsbremsung.",["Eine Warnung.","Eine Betriebsbremsung.","Eine Abfahrverhinderung."],F8)
addm("3.3.1","Halt Einsatz","Wo kommt die Funktion «Halt» § zum Einsatz (Mehrfachauswahl).",["Bei den Hauptsignalen","Zum Schutz von Bahnübergangsanlagen"],["Bei den Vorsignalen","Bei Geschwindigkeitstafeln","Bei Merktafeln"],F8)
add("3.3.1","Halt Überwachungsart","Um welche Art der Überwachung handelt es sich bei der Funktion «Halt» §?","Um eine punktuelle Überwachung.",["Um eine kontinuierliche Überwachung.","Um eine zeitgesteuerte Überwachung.","Um eine Überwachung nur im Rangiermodus."],F8)
add("3.3.1","Rangierhalt Bedingung","Unter welcher Bedingung löst die Funktion «Rangierhalt» § bei Erhalt des entsprechenden Telegramms eine Zwangsbremsung aus?","Sofern sich das Fahrzeug im Rangiermodus befindet.",["Immer, auch bei Zugfahrten.","Nur bei Dunkelheit.","Nur wenn der LF nicht reagiert."],F8)
F9="Die Funktion «Warnung» wird bei Empfang des entsprechenden Telegramms oder bei Erreichen einer Überwachungskurve ausgelöst. Sie macht den LF mit einem optischen und/oder akustischen Signal auf eine Verminderung der Geschwindigkeit aufmerksam. Bleibt eine Reaktion des LF aus, so wird die Geschwindigkeit des Zugs mit einer Zwangsbremsung oder einer Systembremsung gedrosselt, um ein Überfahren des Endpunktes der Zustimmung zur Fahrt oder das zu schnelle Einfahren in einen Gleisabschnitt mit verminderter Geschwindigkeit zu vermeiden. Es handelt sich hierbei um eine punktuelle oder kontinuierliche Überwachung."
addm("3.3.2","Warnung Auslösung","Wann wird die Funktion «Warnung» § ausgelöst (Mehrfachauswahl).",["Bei Empfang des entsprechenden Telegramms","Bei Erreichen einer Überwachungskurve"],["Bei jedem Halt des Zuges","Auf Verlangen des FDL","Beim Überfahren des Endpunktes der Zustimmung"],F9)
add("3.3.2","Warnung Signal","Womit macht die Funktion «Warnung» § den LF auf eine Verminderung der Geschwindigkeit aufmerksam?","Mit einem optischen und/oder akustischen Signal.",["Mit einer Funkdurchsage des FDL.","Mit einer sofortigen Zwangsbremsung.","Mit einem Telegramm an den FDL."],F9)
addm("3.3.2","Warnung keine Reaktion","Womit wird die Geschwindigkeit des Zuges §gedrosselt, wenn der LF auf die Warnung nicht reagiert (Mehrfachauswahl).",["Mit einer Zwangsbremsung","Mit einer Systembremsung"],["Mit einer Betriebsbremsung durch den FDL","Mit der Handbremse","Mit einer Schnellbremsung durch den ZVB"],F9)
addm("3.3.2","Warnung Ziele","Was soll die Funktion «Warnung» § vermeiden (Mehrfachauswahl).",["Das Überfahren des Endpunktes der Zustimmung zur Fahrt","Das zu schnelle Einfahren in einen Gleisabschnitt mit verminderter Geschwindigkeit"],["Das Befahren von Weichen","Die Einfahrt in ein besetztes Gleis","Das zu langsame Fahren"],F9)
add("3.3.2","Warnung Überwachungsart","Um welche Art der Überwachung handelt es sich bei der Funktion «Warnung» §?","Um eine punktuelle oder kontinuierliche Überwachung.",["Nur um eine punktuelle Überwachung.","Nur um eine kontinuierliche Überwachung.","Um eine Überwachung nur im Rangiermodus."],F9)
F10="Für die Überwachung der Geschwindigkeiten werden die Daten des Zuges und der befahrenen Strecke miteinander abgeglichen. Bei Überschreiten der zugelassenen Höchstgeschwindigkeit wird eine Zwangsbremsung respektive eine Systembremsung ausgelöst, der ein optisches und/oder akustisches Signal vorausgehen kann. Unterlässt es der LF, darauf zu reagieren, wird die entsprechende Bremsung ausgelöst. Überwachung der Höchstgeschwindigkeit: Es handelt sich fallweise um die zulässige Höchstgeschwindigkeit des Zugs, des Streckenabschnitts, der Betriebsart oder der Rangierbewegung. Bremskurvenüberwachung: Bei verminderter Geschwindigkeit oder Halt zeigendem Signal wird die Bremskurve kontinuierlich anhand der Zug- und Streckendaten überwacht. Überwachung der Zielgeschwindigkeit: Eine bestimmte Geschwindigkeit kann unabhängig von einer Bremskurve überwacht werden."
add("3.3.3","Abgleich der Daten","Welche Daten werden für die Überwachung der Geschwindigkeiten § miteinander abgeglichen?","Die Daten des Zuges und der befahrenen Strecke.",["Die Daten des Fahrplans und der Fahrordnung.","Die Daten des FDL und des LF.","Die Daten der Fahrleitung und der Weichen."],F10)
add("3.3.3","Überschreiten Höchstgeschwindigkeit","Was wird § bei Überschreiten der zugelassenen Höchstgeschwindigkeit ausgelöst?","Eine Zwangsbremsung respektive eine Systembremsung.",["Nur eine Meldung an den FDL.","Eine Betriebsbremsung durch den FDL.","Nur eine Warnung ohne Bremsung."],F10)
addm("3.3.3","Höchstgeschwindigkeit fallweise","Auf welche zulässige Höchstgeschwindigkeit bezieht sich die Überwachung der Höchstgeschwindigkeit § fallweise (Mehrfachauswahl).",["Auf die des Zugs","Auf die des Streckenabschnitts","Auf die der Betriebsart","Auf die der Rangierbewegung"],["Auf die des Nachbargleises","Auf die des Fahrplans","Auf die des Bahnhofs"],F10)
addm("3.3.3","Bremskurvenüberwachung","Wann wird die Bremskurve § kontinuierlich anhand der Zug- und Streckendaten überwacht (Mehrfachauswahl).",["Bei verminderter Geschwindigkeit","Bei Halt zeigendem Signal"],["Bei Freier Fahrt","Bei jeder Durchfahrt eines Bahnhofs","Bei jedem Anfahren"],F10)
add("3.3.3","Zielgeschwindigkeit","Was gilt § für die Überwachung der Zielgeschwindigkeit?","Eine bestimmte Geschwindigkeit kann unabhängig von einer Bremskurve überwacht werden.",["Sie ist nur mit einer Bremskurve möglich.","Sie ist nur bei Halt zeigendem Signal möglich.","Sie ist nur im Rangiermodus möglich."],F10)
F11="Mit der Abfahrverhinderung kann vermieden werden, dass ein Zug bei der Abfahrt trotz Halt zeigendem Signal den Gefahrenpunkt erreicht. Die Zugbeeinflussung erfolgt mittels einer Balisengruppe oder einer Schleife. Je nach Methode wird der Zug bereits beim Anfahren oder erst beim Überfahren der Balisen abgebremst. Ein optisches und/oder akustisches Signal kann vorausgehen, dem eine Zwangsbremsung folgt."
add("3.3.4","Zweck Abfahrverhinderung","Was kann mit der Abfahrverhinderung § vermieden werden?","Dass ein Zug bei der Abfahrt trotz Halt zeigendem Signal den Gefahrenpunkt erreicht.",["Dass ein Zug zu spät abfährt.","Dass ein Zug im Bahnhof zu lange hält.","Dass ein Zug ohne Abfahrerlaubnis des ZBE abfährt."],F11)
addm("3.3.4","Mittel der Abfahrverhinderung","Womit erfolgt die Zugbeeinflussung bei der Abfahrverhinderung § (Mehrfachauswahl).",["Mit einer Balisengruppe","Mit einer Schleife"],["Mit einem Isolierstoss","Mit einem Lichtsignal","Mit einer Achszählanlage"],F11)
addm("3.3.4","Zeitpunkt Abbremsen","Wann wird der Zug § je nach Methode abgebremst (Mehrfachauswahl).",["Bereits beim Anfahren","Erst beim Überfahren der Balisen"],["Erst am Gefahrenpunkt","Erst nach zwei Minuten","Nur auf Anweisung des FDL"],F11)
add("3.3.4","Signal vor Zwangsbremsung","Was kann der Zwangsbremsung bei der Abfahrverhinderung § vorausgehen?","Ein optisches und/oder akustisches Signal.",["Eine Funkdurchsage des FDL.","Eine Betriebsbremsung durch den LF.","Eine Meldung an den ZBE."],F11)
F12="Das System überwacht, ob sich der Adhäsions-/Zahnradschalter in der richtigen Stellung befindet. Das Fahrzeuggerät löst eine Zwangsbremsung aus, wenn der Schalter nicht innert vorgeschriebener Frist in die richtige Stellung gebracht wird."
add("3.3.5","Überwachung Schalter","Was überwacht das System bei der Umschaltung zwischen Adhäsions- und Zahnradbetrieb §?","Ob sich der Adhäsions-/Zahnradschalter in der richtigen Stellung befindet.",["Ob die Zahnstange frei ist.","Ob die Geschwindigkeit unter 20 km/h liegt.","Ob der Zug vollständig ist."],F12)
add("3.3.5","Zwangsbremsung Schalter","Wann löst das Fahrzeuggerät § bei der Umschaltung Adhäsions-/Zahnradbetrieb eine Zwangsbremsung aus?","Wenn der Schalter nicht innert vorgeschriebener Frist in die richtige Stellung gebracht wird.",["Sobald der Schalter betätigt wird.","Bei jedem Wechsel der Betriebsart.","Wenn der LF die Umschaltung meldet."],F12)
add("4.1","Vorgehen bei Störungen","Nach welchen Bestimmungen ist § bei Störungen der Zugbeeinflussung vorzugehen?","Gemäss den Bestimmungen «Störungen an Sicherheitseinrichtungen».",["Gemäss den Bestimmungen «Arbeiten im Gleisbereich».","Gemäss den Bestimmungen «Fehlender Sicherheits-Zwischenraum».","Gemäss den Vorschriften über Rangierbewegungen."],"Bei Störungen der Zugbeeinflussung ist gemäss den Bestimmungen «Störungen an Sicherheitseinrichtungen» vorzugehen.")
add("4.1.1","Störung zugführendes Fahrzeug","Unter welcher Bedingung darf bei einem gestörten Zugbeeinflussungssystem auf dem zugführenden Fahrzeug § ohne Einschränkungen verkehrt werden?","Wenn die für die Infrastruktur vorgesehenen Funktionen durch ein anderes Zugbeeinflussungssystem gewährleistet sind.",["Wenn der LF die Störung dem FDL gemeldet hat.","Wenn mit höchstens 40 km/h gefahren wird.","Wenn ein zweiter LF mitfährt."],"Ist ein Zugbeeinflussungssystem gestört, darf ohne Einschränkungen verkehrt werden, wenn die für die Infrastruktur vorgesehenen Funktionen durch ein anderes Zugbeeinflussungsystem gewährleistet sind.")
run(seed=1563,new_reg=('r7','R 300.7','R 300.7 ZUGBEEINFLUSSUNG'))
